import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BEUshCVJ.js";const m=JSON.parse('{"title":"实机测试清单","description":"","frontmatter":{},"headers":[],"relativePath":"zh/test-checklist.md","filePath":"zh/test-checklist.md","lastUpdated":1793456875000}'),o={name:"zh/test-checklist.md"};function r(s,e,n,c,h,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="实机测试清单" tabindex="-1">实机测试清单 <a class="header-anchor" href="#实机测试清单" aria-label="Permalink to &quot;实机测试清单&quot;">​</a></h1><p>本页列出只能在真实 Windows 电脑上完成的检查：音频、快捷键、面板、语音合成和真实供应商延迟。其余部分由自动化测试覆盖。每次发布前，用 <code>scoop install meetcue</code> 安装后逐项检查。</p><p>某项未通过时，记下错误码（如有），<a href="/meetcue/zh/troubleshooting/diagnostics">导出诊断信息</a>并<a href="https://github.com/Amazingkenneth/meetcue/issues/new?template=bug.yml" target="_blank" rel="noreferrer">提交 Issue</a>。</p><h2 id="macos-验收检查" tabindex="-1">macOS 验收检查 <a class="header-anchor" href="#macos-验收检查" aria-label="Permalink to &quot;macOS 验收检查&quot;">​</a></h2><p>在 macOS 13 及以上版本的 Apple 芯片和 Intel Mac 上，从应用程序目录运行打包后的应用。CI 会构建两种架构并检查版本、签名和隐私元数据，但无法处理系统隐私弹窗或验证真实音频硬件。</p><ol><li>在尚未授权时启动。拒绝屏幕/音频录制后应显示 <code>MC-AUD-006</code>；在隐私与安全性中允许，再退出重开。拒绝麦克风后应显示 <code>MC-AUD-002</code>，允许后重新开始采集。</li><li>用应用包内的可执行文件运行 <code>--self-test</code>，戴耳机并在麦克风测试时说话。确认系统声音测试音和麦克风都通过。自动自检可能跳过屏幕共享隐藏检查，需在实际会议软件中手动验证。</li><li>播放会议或视频，确认双通道电平、实时转写和提示；多次暂停/继续和停止/开始。让系统声音静音一分钟后恢复播放。</li><li>选择 USB/耳机麦克风后拔出，并切换系统默认输入。确认采集跟随设置、报告设备变化并恢复。</li><li>试听中英文语音，再打开问题语音转文字运行模拟面试。确认应用朗读的问题进入远端通道，停止和再问一次可打断朗读。</li><li>检查面板透明、快捷键、点击穿透、多 Retina 显示器位置和普通设置窗口焦点。在实际会议软件中验证屏幕共享可见性：部分 macOS 录制客户端可能忽略窗口排除设置。</li><li>保存密钥后重启，检查钥匙串持久化与开机启动；确认清除全部数据会删除密钥和设置；覆盖旧应用后确认仍可启动。</li></ol><h2 id="先运行自检" tabindex="-1">先运行自检 <a class="header-anchor" href="#先运行自检" aria-label="Permalink to &quot;先运行自检&quot;">​</a></h2><ul><li>[ ] <code>MeetCue.exe --version</code> 输出预期的版本号。</li><li>[ ] 将扬声器静音或戴上耳机，运行 <code>MeetCue.exe --self-test</code>，所有项目都显示通过。</li></ul><h2 id="设置与演示" tabindex="-1">设置与演示 <a class="header-anchor" href="#设置与演示" aria-label="Permalink to &quot;设置与演示&quot;">​</a></h2><ul><li>[ ] 首次启动出现设置向导；填入语音识别和模型密钥后，延迟探测给出结果表和组合排名。</li><li>[ ] <code>MeetCue.exe --demo</code> 能完整播放示例面试。</li></ul><h2 id="音频" tabindex="-1">音频 <a class="header-anchor" href="#音频" aria-label="Permalink to &quot;音频&quot;">​</a></h2><ul><li>[ ] 播放视频时“系统声音”电平条跳动；对着麦克风说话时“麦克风”电平条跳动。</li><li>[ ] 使用外放而不是耳机时，对方的话不会被当成你说的。</li><li>[ ] 拔插耳机或切换默认设备后，采集自动恢复。</li></ul><h2 id="会议" tabindex="-1">会议 <a class="header-anchor" href="#会议" aria-label="Permalink to &quot;会议&quot;">​</a></h2><ul><li>[ ] 真实会议中，对方问完问题约 1.5 秒内出现问题块和要点，底栏延迟数字与之相符。</li><li>[ ] 回答时，讲到的要点打勾，下一条高亮。</li><li>[ ] 你回答时对方插话提问，新问题进入 <strong>下一问</strong>，当前提示不被替换。</li><li>[ ] 九个快捷键全部生效，按住移动快捷键时面板持续移动、松开即停；会议软件自己的快捷键（如 Teams 的 <code>Ctrl+Shift+M</code>）仍然正常。</li><li>[ ] 点击面板不会让会议窗口失去焦点。</li><li>[ ] 共享整个屏幕时，对方看不到面板。</li></ul><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><ul><li>[ ] 托盘菜单的 <strong>模拟面试…</strong>、空闲面板上的 <strong>试试模拟面试</strong>、<strong>设置 › 通用 › 打开模拟面试</strong> 和设置向导中的 <strong>完成并开始模拟面试</strong> 都能打开模拟面试窗口。</li><li>[ ] 声音检查这一步两条电平都会跳动，中英文语音列表都有内容，点 <strong>试听</strong> 会用所选语音读出示例。</li><li>[ ] 练习窗口和面板上的 <strong>再问一遍</strong> 都能从头重读当前这道题。</li><li>[ ] 朗读时咳嗽或“嗯”一声不会把问题打断，正常回答则会。</li><li>[ ] 每个内置示例都能用 <strong>使用</strong> 载入；至少按<a href="/meetcue/zh/guide/mock-interview#self-test-plan">自测方案</a>完成第 1 轮和第 3 轮。</li><li>[ ] 用示例字幕和示例问题列表各练一轮。</li><li>[ ] <strong>问题语音转文字</strong> 开启和关闭时都能出提示。</li><li>[ ] 四档提示难度切换正常。</li><li>[ ] 复盘报告可以导出。</li></ul><h2 id="语言与错误" tabindex="-1">语言与错误 <a class="header-anchor" href="#语言与错误" aria-label="Permalink to &quot;语言与错误&quot;">​</a></h2><ul><li>[ ] 在设置中切换 English / 简体中文，面板、托盘菜单、错误信息和练习报告即时切换。</li><li>[ ] 故意填错一个密钥，错误提示带错误码；点击 <strong>查看解决办法</strong> 打开当前语言的文档并定位到该错误码。</li><li>[ ] 诊断压缩包里没有任何密钥。</li></ul><h2 id="升级与文档" tabindex="-1">升级与文档 <a class="header-anchor" href="#升级与文档" aria-label="Permalink to &quot;升级与文档&quot;">​</a></h2><ul><li>[ ] 执行 <code>scoop update meetcue</code> 后，设置、密钥、延迟历史和练习记录都还在。</li><li>[ ] 文档站点在手机和电脑上都便于阅读；切换语言后停留在对应页面；搜索中文关键词能找到结果。</li></ul>',20)])])}const g=l(o,[["render",r]]);export{m as __pageData,g as default};
